def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    me_d = 0
    for i in range(n):
        if op[i] == 'C':
            op_c += 1
        if me[i] == 'D':
            me_d += 1

    recent_len = 12 if n >= 12 else n
    recent_op_c = 0
    for i in range(n - recent_len, n):
        if op[i] == 'C':
            recent_op_c += 1

    punish = 0
    forgive = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'D':
                punish += 1
            else:
                forgive += 1

    op_d_run = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        op_d_run += 1
        i -= 1

    very_coop = op_c * 4 >= n * 3
    mostly_coop = op_c * 2 >= n
    recent_all = recent_op_c == recent_len

    if op_c == 0:
        return 'D'
    if n >= 20 and op_c <= max(2, n // 5):
        return 'D'
    if n >= 12 and recent_op_c <= 1 and op_c <= max(3, n // 3):
        return 'D'
    if op_d_run >= 4 and not mostly_coop:
        return 'D'

    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        if last_me == 'D':
            if op_d_run >= 4 and recent_op_c * 3 <= recent_len and not mostly_coop:
                return 'D'
            if very_coop:
                return 'C'
            if mostly_coop and recent_op_c >= max(2, recent_len // 3):
                return 'C'
            if forgive >= punish and recent_op_c >= max(1, recent_len // 4):
                return 'C'
            if recent_op_c > 0:
                return 'C'
            return 'D'

        provoked = False
        if n >= 2 and me[-2] == 'D' and op[-2] == 'C':
            provoked = True

        if provoked:
            if very_coop:
                return 'C'
            if recent_all and mostly_coop and forgive >= punish:
                return 'C'
            if recent_op_c >= recent_len - 1 and op_c >= n // 2 and forgive > punish:
                return 'C'

        return 'D'

    if last_me == 'D':
        if punish == 0 and forgive > 0 and recent_all and op_c * 3 >= n:
            if n >= 50:
                return 'D'
        return 'C'

    if recent_all:
        if punish == 0 and forgive > 0 and op_c * 3 >= n and n >= 50:
            return 'D'

        if me_d == 0 and n >= 50 and n <= 60 and very_coop and rng.random() < 0.20:
            return 'D'

        if me_d == 0 and n == 70 and mostly_coop and rng.random() < 0.35:
            return 'D'

        return 'C'

    if recent_op_c * 3 >= recent_len * 2 and mostly_coop:
        return 'C'

    if recent_op_c * 3 <= recent_len and op_c * 3 <= n * 2:
        return 'D'

    return 'C'
